// Groups unsent articles by category into a print-ready HTML page for Gotenberg.
// ===== SETTINGS =====
const TEST_CHAT  = 'YOUR_PRIVATE_CHAT_ID';        // your private chat
const GROUP_CHAT = '-100XXXXXXXXXX';    // the group
const MAX_PER_CATEGORY = 8;             // cap per category; picks alternate between sources so one site can't fill it
// ====================
// Where it goes:
//   "Test (send to me)" trigger          -> your private chat, labelled [TEST], marks nothing
//   "10:00 and 16:00" trigger            -> group, marks articles as sent
//      (on schedule, or when you run it by hand from that trigger = "send to group now")

const IS_TEST = (() => { try { return $('Test (send to me)').isExecuted; } catch (e) { return false; } })();
const CHAT_ID = IS_TEST ? TEST_CHAT : GROUP_CHAT;
const ORDER = ['SEBI & AMFI', 'Insurance', 'Global News', 'US Market', 'Indian Market', 'MF Industry'];

const rows = $input.all().map(i => i.json).filter(r => r.url);
const now = $now.setZone('Asia/Kolkata');
const label = (IS_TEST ? '[TEST] ' : '') + (now.hour < 13 ? 'Morning Digest' : 'Afternoon Digest');
const stamp = now.toFormat('dd LLL yyyy, HH:mm');

if (!rows.length) {
  return [{ json: { empty: true, chatId: CHAT_ID, isTest: IS_TEST, testChat: TEST_CHAT,
    text: `${label} | ${stamp}\nNo new articles in your categories.` } }];
}

const SOURCE_LABEL = { cafemutual: 'Cafemutual', moneycontrol: 'Moneycontrol', cnbctv18: 'CNBC TV18' };
const esc = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const all = {};
rows.forEach(r => (all[r.category] ??= []).push(r));
// Round-robin across sources (newest first within each) so every source gets a share of each category.
const groups = {};
for (const [cat, list] of Object.entries(all)) {
  const bySource = {};
  list.forEach(r => (bySource[r.source] ??= []).push(r));
  const queues = Object.values(bySource);
  const picked = [];
  while (picked.length < MAX_PER_CATEGORY && queues.some(q => q.length)) {
    for (const q of queues) if (q.length && picked.length < MAX_PER_CATEGORY) picked.push(q.shift());
  }
  groups[cat] = picked;
}
const shownCount = Object.values(groups).reduce((n, g) => n + g.length, 0);
const cats = [...ORDER.filter(c => groups[c]), ...Object.keys(groups).filter(c => !ORDER.includes(c))];

const sections = cats.map(c => `
  <section>
    <h2>${esc(c)} <span class="count">${groups[c].length}</span></h2>
    <ol>${groups[c].map(r => `
      <li><a href="${esc(r.url)}">${esc(r.title)}</a><span class="src">${esc(SOURCE_LABEL[r.source] || r.source)}</span></li>`).join('')}
    </ol>
  </section>`).join('');

const html = `<!doctype html><html><head><meta charset="utf-8"><title>${label}</title><style>
  @page { size: A4; margin: 16mm 14mm; }
  body { font-family: Arial, Helvetica, sans-serif; color: #1c2230; font-size: 10.5pt; margin: 0; }
  header { border-bottom: 2px solid #16233F; padding-bottom: 8px; margin-bottom: 14px; }
  header h1 { font-size: 18pt; margin: 0; color: #16233F; }
  header p { margin: 4px 0 0; color: #5A7099; font-size: 9.5pt; }
  h2 { font-size: 12.5pt; color: #16233F; margin: 16px 0 6px; padding-bottom: 3px; border-bottom: 1px solid #B8860B; }
  .count { font-size: 9pt; color: #fff; background: #2C4470; border-radius: 8px; padding: 1px 7px; vertical-align: middle; }
  ol { margin: 0; padding-left: 20px; }
  li { margin: 0 0 6px; line-height: 1.35; page-break-inside: avoid; }
  a { color: #1c2230; text-decoration: none; }
  .src { color: #8a93a6; font-size: 8.5pt; margin-left: 6px; }
  footer { margin-top: 18px; font-size: 8pt; color: #8a93a6; }
</style></head><body>
  <header><h1>${label}</h1><p>${stamp} IST &middot; ${shownCount} articles</p></header>
  ${sections}
  <footer>Headlines and links only. Read full articles on the source sites.</footer>
</body></html>`;

const caption = `${label} | ${stamp}\n` + cats.map(c => `${c}: ${groups[c].length}`).join('\n');

return [{
  json: {
    empty: false, chatId: CHAT_ID, caption, isTest: IS_TEST, testChat: TEST_CHAT,
    cutoff: IS_TEST ? '1970-01-01' : rows[0].cutoff,   // test runs don't mark anything as sent
    fileName: `${label.replace('[TEST] ', 'TEST-').replace(' ', '-')}-${now.toFormat('yyyy-LL-dd-HHmm')}`,
  },
  binary: {
    data: { data: Buffer.from(html, 'utf8').toString('base64'), mimeType: 'text/html', fileName: 'index.html', fileExtension: 'html' },
  },
}];

