// Google News search feeds for debate-worthy finance stories (last 24h, India edition).
// ===== SETTINGS =====
const DRAFT_ON = 'morning';      // which scheduled run drafts: 'morning' | 'afternoon' | 'both' (manual runs always draft)
const QUERIES = [
  'SEBI order OR penalty OR ban',
  'SEBI new rules investors',
  'finfluencer SEBI',
  'mutual fund charges OR "expense ratio" OR "exit load"',
  'IRDAI penalty OR mis-selling OR "claim rejection"',
  'income tax investors OR LTCG OR STT',
  'RBI repo rate OR EMI OR loan rates',
  'IPO listing loss OR IPO controversy',
  'India tariff OR trade deal',
  'bank fraud OR NPA OR "wilful defaulter"',
];
// ====================

const d = $('Build Digest').first().json;
const isMorning = $now.setZone('Asia/Kolkata').hour < 13;
const scheduledMatch = DRAFT_ON === 'both' || (DRAFT_ON === 'morning') === isMorning;
if (!d.isTest && !scheduledMatch) return [];            // not a drafting run: stop here

return QUERIES.map(q => ({ json: {
  query: q,
  url: 'https://news.google.com/rss/search?q=' + encodeURIComponent(q + ' when:1d') + '&hl=en-IN&gl=IN&ceid=IN:en',
} }));

// Pools today's digest headlines + Google News debate searches, and asks the model for the 5 most debatable topics.
// ===== SETTINGS =====
const TOPICS = 5;                // topics per day
const FROM_DIGEST = 20;          // max headlines taken from today's digest
const FROM_SEARCH = 30;          // max headlines taken from the Google News searches
const MODEL = 'openai/gpt-oss-120b';      // used only by the raw-API variant; the Groq Model node sets the model
const STYLE = 'Punchy and opinionated, but factual. 1-2 relevant hashtags. No emojis.';
// ====================

const d = $('Build Digest').first().json;
const shuffle = a => [...a].sort(() => Math.random() - 0.5);
const norm = s => String(s).toLowerCase().replace(/\s+-\s+[^-]+$/, '').replace(/[^a-z0-9 ]/g, '').trim();

// Skip stories already used on earlier days (kept in workflow memory; saved on scheduled runs).
const memory = $getWorkflowStaticData('global');
const used = new Set(memory.usedTopics || []);

const digest = $('Fetch Unsent').all().map(i => i.json)
  .filter(r => r.url && r.title)
  .map(r => ({ title: r.title, url: r.url, from: r.category }));
const search = $input.all().map(i => i.json)
  .filter(j => !j.error && j.title && j.link)
  .map(j => ({ title: String(j.title).trim(), url: j.link, from: 'News search' }));

const seen = new Set();
const pool = [];
for (const c of [...shuffle(digest).slice(0, FROM_DIGEST), ...shuffle(search).slice(0, FROM_SEARCH)]) {
  const k = norm(c.title);
  if (!k || seen.has(k) || used.has(k)) continue;
  seen.add(k);
  pool.push(c);
}
if (pool.length < TOPICS) return [{ json: { chatId: d.testChat, error: `Only ${pool.length} candidate stories today; drafts skipped.` } }];

const system = [
  'You write X (Twitter) posts for a general finance news and commentary page in India.',
  'Goal: spark debate and replies on genuinely contested finance stories, while staying factual and legally safe.',
  'Prefer stories that divide opinion: rules that affect investors, costs passed to customers, regulatory penalties,',
  'policy U-turns, tax changes, tariffs or trade fights, clear winners vs losers. Pick different stories, not five versions of one.',
  'Rules:',
  '- Stick to facts in the headline. Never invent numbers, names, quotes or motives.',
  '- Criticise decisions and policies, never people. No insults. Call allegations "alleged" unless proven.',
  '- No investment advice, buy/sell calls, price targets, return predictions or hype about specific stocks or funds.',
  '- Nothing on religion, caste, communities or party politics.',
  '- Frame the debate; do not present opinion as fact.',
  '- Each post under 260 characters including hashtags. Plain text, no markdown.',
  `- Style: ${STYLE}`,
  'Respond in JSON only.',
].join('\n');

const user = [
  'Headlines:',
  ...pool.map((p, i) => `${i + 1}. ${p.title}`),
  '',
  `Choose the ${TOPICS} most debatable headlines. For each, write:`,
  '- "hot_take": a bold post that invites disagreement,',
  '- "poll": a poll-style question with 2-3 short options on separate lines.',
  'Return JSON: {"topics":[{"pick":<headline number>,"why":"<under 15 words: why people will argue>","hot_take":"...","poll":"..."}]}',
].join('\n');

return [{
  json: {
    pool, chatId: d.chatId, testChat: d.testChat, isTest: d.isTest,
    systemPrompt: system, userPrompt: user,
    body: { model: MODEL, temperature: 0.8, max_tokens: 1800, response_format: { type: 'json_object' },
            messages: [{ role: 'system', content: system }, { role: 'user', content: user }] },
  },
}];

// Builds the X drafts as a print-ready HTML page (converted to PDF next). Errors go only to your private chat.
const t = $('Pick Draft Topic').first().json;
const fail = msg => [{ json: { ok: false, chatId: t.testChat, text: `X drafts: ${msg}` } }];
if (t.error) return fail(t.error);

const r = $input.first().json;
const raw = r?.text ?? r?.choices?.[0]?.message?.content;   // LLM Chain node or raw API reply
let topics = [];
try {
  const s = String(raw);
  topics = JSON.parse(s.slice(s.indexOf('{'), s.lastIndexOf('}') + 1)).topics || [];
} catch (e) { /* handled below */ }
if (!topics.length) {
  const err = r?.error?.message || r?.error || r?.message || String(raw || JSON.stringify(r)).slice(0, 300);
  return fail(`generation failed: ${err}`);
}

const now = $now.setZone('Asia/Kolkata');
const date = now.toFormat('dd LLL yyyy');
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const count = s => [...String(s || '').trim()].length;
const badge = s => `<span class="chars${count(s) > 280 ? ' over' : ''}">${count(s)} / 280</span>`;

const usedNow = [];
const cards = topics.map((x, i) => {
  const story = t.pool[(parseInt(x.pick, 10) || 0) - 1];
  if (story) usedNow.push(story.title);
  return `
  <section class="topic">
    <div class="num">${i + 1}</div>
    <div class="body">
      ${x.why ? `<p class="why">${esc(x.why)}</p>` : ''}
      ${story
        ? `<p class="src"><a href="${esc(story.url)}">${esc(story.title)}</a></p>`
        : '<p class="src missing">Source headline not identified. Check before posting.</p>'}
      <div class="post"><div class="label">Hot take ${badge(x.hot_take)}</div><div class="text">${esc(String(x.hot_take || '').trim())}</div></div>
      <div class="post"><div class="label">Poll ${badge(x.poll)}</div><div class="text">${esc(String(x.poll || '').trim())}</div></div>
    </div>
  </section>`;
}).join('');

const title = `${t.isTest ? '[TEST] ' : ''}X Debate Drafts`;
const html = `<!doctype html><html><head><meta charset="utf-8"><title>${title}</title><style>
  @page { size: A4; margin: 14mm 14mm; }
  body { font-family: Arial, Helvetica, sans-serif; color: #1c2230; font-size: 10.5pt; margin: 0; }
  header { border-bottom: 2px solid #16233F; padding-bottom: 8px; margin-bottom: 12px; }
  header h1 { font-size: 18pt; margin: 0; color: #16233F; }
  header p { margin: 4px 0 0; color: #5A7099; font-size: 9.5pt; }
  .topic { display: flex; gap: 10px; border: 1px solid #d9dee8; border-radius: 6px; padding: 10px 12px; margin-bottom: 10px; page-break-inside: avoid; }
  .num { flex: 0 0 26px; height: 26px; border-radius: 13px; background: #16233F; color: #fff; font-weight: bold; text-align: center; line-height: 26px; }
  .body { flex: 1; min-width: 0; }
  .why { margin: 0 0 4px; font-weight: bold; color: #16233F; }
  .src { margin: 0 0 8px; font-size: 9.5pt; overflow-wrap: anywhere; }
  .src a { color: #2C4470; text-decoration: none; }
  .src.missing { color: #b42318; }
  .post { margin-top: 6px; }
  .label { font-size: 8.5pt; text-transform: uppercase; letter-spacing: .4px; color: #5A7099; margin-bottom: 2px; }
  .text { white-space: pre-wrap; overflow-wrap: anywhere; background: #f5f7fb; border-left: 3px solid #B8860B; padding: 6px 8px; line-height: 1.4; }
  .chars { float: right; text-transform: none; color: #8a93a6; }
  .chars.over { color: #b42318; font-weight: bold; }
  footer { margin-top: 12px; font-size: 8pt; color: #8a93a6; }
</style></head><body>
  <header><h1>${title}</h1><p>${date} &middot; ${topics.length} topics &middot; Verify facts in each source article before posting.</p></header>
  ${cards}
  <footer>AI-generated drafts for internal review. Commentary only; not investment advice.</footer>
</body></html>`;

// Remember used stories so they are not picked again (last 200; saved on scheduled runs).
const norm = s => String(s).toLowerCase().replace(/\s+-\s+[^-]+$/, '').replace(/[^a-z0-9 ]/g, '').trim();
const memory = $getWorkflowStaticData('global');
memory.usedTopics = [...(memory.usedTopics || []), ...usedNow.map(norm)].slice(-200);

return [{
  json: {
    ok: true, chatId: t.chatId,
    caption: `${title} | ${date} | ${topics.length} topics`,
    fileName: `${t.isTest ? 'TEST-' : ''}X-Drafts-${now.toFormat('yyyy-LL-dd')}`,
  },
  binary: { data: { data: Buffer.from(html, 'utf8').toString('base64'), mimeType: 'text/html', fileName: 'index.html', fileExtension: 'html' } },
}];
